  ('835fc35d-87cd-4980-8bb5-980f1e2c055f', '95d38b90-1d15-4c16-99d3-9cfff27f4036', '9fea80d0-b73e-45ad-9bd3-6d66972be618', $q$Solomon$q$, $q$2Y6 Further expl succes - NOT develop-Solomon$q$, 6, $q$$q$, $q$$q$, $q$2. Do not add this find to Solomon production. $q$, null, true, null, null, null, null, 0, true, $q$9f40a728-b4b4-4c59-8185-6ab79577876f$q$),
  ('4bb9ba0c-faff-4f61-a3ce-87b4e511f70b', '95d38b90-1d15-4c16-99d3-9cfff27f4036', 'e40fcdf7-31b9-4b9b-8cff-e924d0cc49e5', $q$Amura$q$, $q$Amura - Digitization project delivery-Amura$q$, 6, $q$AMURA - Digitization project delivery$q$, $q$<p>By leveraging digital tools to enhance collaboration and decision-making the digitization project has led to a 25% reduction in operating costs and a 15% increase in production efficiency. <strong>Total effect is a reduced OPEX across the portfolio by 15%.</strong></p>$q$, $q$$q$, null, true, null, null, null, null, 0, true, $q$88e5337e-0f75-4922-8b47-47f8a1fd86b8$q$),
  ('0b91ea49-ba75-4b8a-94f7-19e08d1970db', '95d38b90-1d15-4c16-99d3-9cfff27f4036', 'e40fcdf7-31b9-4b9b-8cff-e924d0cc49e5', $q$Amura$q$, $q$Amura - Delivery Digital Oil Fields.-Amura$q$, 6, $q$AMURA - Delivery research use of digital oil fields$q$, $q$<p>Digital oil field technologies, including IoT sensors and real-time data analytics, <strong>has resulted in 20% increase in production efficiency and a 40% reduction in maintenance costs, in total OPEX is reduced by 20%.</strong></p>$q$, $q$$q$, null, true, null, null, null, null, 0, true, $q$a0b86130-5e8a-4b8b-b6a5-1fc2f5885248$q$),
  ('7a989246-0dba-456f-8e06-14dcbe1419be', '95d38b90-1d15-4c16-99d3-9cfff27f4036', 'df6ae15a-a536-442d-b6e8-ee21e8e68341', $q$Nimbus$q$, $q$Successful negotiations-Nimbus$q$, 6, $q$NIMBUS - Negotiations successful$q$, $q$<p>The negotiations with the local fishing community has been successful.</p><p><br></p><p><strong>The Nimbus Offshore Wind project will precede as planned.</strong></p>$q$, $q$$q$, null, null, null, null, null, null, 0, true, $q$4cd2ead0-ba98-4a11-beb3-acc51073c6e4$q$),
  ('95c099df-f87a-4674-820a-ed66d98fc759', '95d38b90-1d15-4c16-99d3-9cfff27f4036', 'df6ae15a-a536-442d-b6e8-ee21e8e68341', $q$Nimbus$q$, $q$Escalating cirumstances-Nimbus$q$, 6, $q$NIMBUS - Community Resistance Escalates$q$, $q$<p>Due to escalating protests and governmental involvement, your company have been issued with a fine of $1 M/MW to compensate the local fishing community.</p><p><br></p><p>Additionally, you are required to invest in environmental studies to protect marine wildlife. <strong>The project is delayed for 2 years.</strong></p>$q$, $q$$q$, null, null, null, null, null, null, 0, true, $q$6a2e0f01-fbe5-48dc-b0af-94c95603a3a8$q$),
  ('e99d2157-01f1-48c8-b5f0-5d0e49bb9a28', '95d38b90-1d15-4c16-99d3-9cfff27f4036', '13d5dc12-7917-4a71-bd03-736d0db2b0f2', $q$Tempest$q$, $q$2Endangered species$q$, 6, $q$$q$, $q$$q$, $q$2. Reject demands and proceed as planned. Increases CAPEX with $0.1 M/MW due to legal costs. $q$, null, null, null, null, null, null, 0, true, null),
  ('c0fa070c-932c-4430-955e-fd400da4b408', '95d38b90-1d15-4c16-99d3-9cfff27f4036', '7b358cb6-9eaa-42bc-beec-a844c5c02820', $q$Photon$q$, $q$1 Industrial dust$q$, 6, $q$Photon Solar - Industrial dust$q$, $q$<p>A nearby industrial area is causing dust and pollution which is negatively affecting the Photon Solar project's energy output. The government is refusing to interfere due to the industrial operations' economic importance to the country.</p><p><br></p><p><strong>Capacity factor has been reduced by 7%.</strong></p><p><br></p><p>You have two options for mitigation:</p>$q$, $q$1. Implement more frequent cleaning schedules and increase maintenance. Increases OPEX to $ 0.04 MUSD/MW. Will increase capacity factor with 5% after 1 year.$q$, null, null, null, 0.28, null, null, 0, true, null),
  ('55453eb5-4794-47fc-953d-32cf622c498c', '95d38b90-1d15-4c16-99d3-9cfff27f4036', '73a2ac01-de5f-4cbc-9ed1-a429d5ab2935', $q$Borealis$q$, $q$2 Icing issues$q$, 6, $q$$q$, $q$$q$, $q$2. Deploy regular de-icing maintenance crews. Increases annual OPEX by $0.02 MUSD/MW. Capacity factor will be reduced by 5%.$q$, null, null, null, null, null, null, 0, true, null),
  ('7df3d852-dcd5-45cb-854c-3da0c3e15694', '95d38b90-1d15-4c16-99d3-9cfff27f4036', '3d954298-e0c2-4a9f-ad33-dc557f0f74b1', $q$Breeze$q$, $q$Successful negotiations$q$, 6, $q$Breeze Offshore Wind - Negotiations successful $q$, $q$<p>The negotiations with the local fishing community has been successful.</p><p><br></p><p><strong>The Breeze Offshore Wind project will precede as planned.</strong></p>$q$, $q$$q$, null, null, null, null, null, null, 0, true, $q$da37c44a-9285-4975-af50-f778dbed6cc4$q$),
  ('5ab03801-c0ae-431b-9b7a-fde8eac1605a', '95d38b90-1d15-4c16-99d3-9cfff27f4036', '3d954298-e0c2-4a9f-ad33-dc557f0f74b1', $q$Breeze$q$, $q$Escalating circumstances$q$, 6, $q$Breeze Offshore Wind - Community Resistance Escalates$q$, $q$<p>Due to escalating protests and governmental involvement, <strong>your company have been issued with a fine of $1 M/MW</strong> to compensate the local fishing community.</p><p><br></p><p>Additionally, you are required to invest in environmental studies to protect marine wildlife. <strong>The project is delayed for 2 years.</strong></p>$q$, $q$$q$, null, null, null, null, null, null, 0, true, $q$69ee800a-90d1-4fbe-a1b5-8f9153921ab6$q$),
  ('9a193ae1-98c3-4699-a422-7bdd44086ce8', '95d38b90-1d15-4c16-99d3-9cfff27f4036', '73a2ac01-de5f-4cbc-9ed1-a429d5ab2935', $q$Borealis$q$, $q$1 Icing issues$q$, 6, $q$Borealis Onshore Wind - Icing Issues$q$, $q$<p>Changing weather conditions have led to significant icing on turbine blades, reducing efficiency and increasing maintenance needs. Local authorities are concerned regarding safety for nearby roads and villages.</p><p><br></p><p><strong>All production has been stopped until security measures have been taken.</strong></p><p><br></p><p>You have two options for mitigation:</p>$q$, $q$1. Install blade heating system. Additional CAPEX of $0.2 MUSD/MW. Increases annual OPEX by $0.03 MUSD/MW.$q$, null, null, null, null, $q$renewable$q$, null, 0, true, null),
  ('3db7de3f-805f-40d0-8d80-2c1dfd6634e8', '95d38b90-1d15-4c16-99d3-9cfff27f4036', 'b974d6d4-341c-4e38-bd4e-db03bbbb0ef5', $q$Helios$q$, $q$1 Curtailment issues$q$, 6, $q$Helios Solar - Limited grid capacity$q$, $q$<p>Due to the outdated infrastructure in Exlandia, the electricity grid is experiencing limited transmission capacity during peak solar production hours.</p><p><strong>The project's capacity factor has been reduced by 5%, and production is halted until a solution is found.</strong></p><p><br></p><p>You have two options for mitigation:</p>$q$, $q$1. Contribute to upgrading local transmission capacity. Adds a CAPEX of $0.2 m/MW. Increases OPEX with $0.005 m/MW. Capacity factor will be restored to 28% after 2 years.$q$, null, null, null, null, null, null, 0, true, null),
  ('466ca924-8aa9-4ebe-808b-d74337cde265', '95d38b90-1d15-4c16-99d3-9cfff27f4036', '13d5dc12-7917-4a71-bd03-736d0db2b0f2', $q$Tempest$q$, $q$1Endangered species$q$, 6, $q$TEMPEST - Endangered Species Protection Requirements$q$, $q$<p>The discovery of an endangered marine species near the wind farm site requires additional measures to protect their habitat.</p><p><br></p><p><strong>Due to pressure from local NGO's, the Government is insisting you take action to minimize disturbance and protect marine wildlife in this area.&nbsp;</strong></p>$q$, $q$1. Initiate negotiations. Increases CAPEX with $0.5 M/MW and stops production for 1 year.$q$, null, null, null, null, null, null, 0, true, null),
  ('5e7cc55c-c651-49f0-8d57-80462a1d1f10', '95d38b90-1d15-4c16-99d3-9cfff27f4036', '8e1c38b8-b573-4105-8337-c74615da89cc', $q$Lumen$q$, $q$1 Industrial dust-Lumen$q$, 6, $q$LUMEN - Industrial dust$q$, $q$<p>A nearby industrial area is causing dust and pollution which is negatively affecting the Lumen Solar project's energy output. The government is refusing to interfere due to the industrial operations' economic importance to the country.</p><p><strong>Capacity factor has been reduced by 7%.</strong></p><p><br></p><p>You have two options for mitigation:</p>$q$, $q$1. Implement frequent cleaning schedules and increase maintenance. Increased OPEX of $ 0.02 MUSD/MW. Increased CF with 5% after 1 year.$q$, null, null, null, null, null, null, 0, true, null),
  ('01077a23-0f29-4040-a5f3-633912e6dee5', '95d38b90-1d15-4c16-99d3-9cfff27f4036', '474732ee-2ee2-4e7f-98c7-74d332a4bf74', $q$Helena$q$, $q$Helena - Advanced Analytics research-Helena$q$, 7, $q$HELENA - Advanced Analytics research programme$q$, $q$<p>Advanced analytics AI/ML program has, by analyzing data from all wells, <strong>resulted in 10% increased production.</strong></p>$q$, $q$$q$, null, true, null, null, null, null, 0, true, $q$ce575af3-8feb-4c37-ac6f-17a8e39cad31$q$),
