  ('b852c28c-081d-4d94-bdaa-ca5d03683ce4', '95d38b90-1d15-4c16-99d3-9cfff27f4036', 'f7e896d1-dea0-43ce-a7a7-7b9426ac8c35', $q$Andrea$q$, $q$ANDREA - Digitization project delivery-Andrea$q$, 7, $q$ANDREA - Digitization project delivery$q$, $q$<p>By leveraging digital tools to enhance collaboration and decision-making the digitization project has led to a 25% reduction in operating costs and a 15% increase in production efficiency. <strong>Total effect is a reduced OPEX across the portfolio by 15%.</strong></p>$q$, $q$$q$, null, true, null, null, null, null, 0, true, $q$9dd324e2-4710-4fe7-8616-38e2ea0f5b31$q$),
  ('8057c3d2-c91a-41b8-b05f-f413c0879c3e', '95d38b90-1d15-4c16-99d3-9cfff27f4036', 'f2cac7f8-f0fb-4a03-8e9a-10285af2d1c8', $q$Nostro$q$, $q$Nostro - Advanced Analytics research-Nostro$q$, 7, $q$NOSTRO - Advanced Analytics research programme$q$, $q$<p>Advanced analytics AI/ML program has, by analyzing data from all wells, <strong>resulted in 10% increased production.</strong></p>$q$, $q$$q$, null, true, null, null, null, null, 0, true, $q$9eef5215-344c-42ca-aa33-6b5f1fe6fcf8$q$),
  ('53dab88f-5436-4b78-aa8c-800a79affa70', '95d38b90-1d15-4c16-99d3-9cfff27f4036', 'f2cac7f8-f0fb-4a03-8e9a-10285af2d1c8', $q$Nostro$q$, $q$Nostro - Research Digital Oil Fields-Nostro$q$, 7, $q$NOSTRO - Research use of Digital Oil Fields$q$, $q$<p>Digital oil field technologies, including IoT sensors and real-time data analytics, <strong>has resulted in reduction in maintenance costs, in total OPEX is reduced by 10%.</strong></p>$q$, $q$$q$, null, true, null, null, null, null, 0, true, $q$63f8dc86-79d5-40d7-916a-d6625f2b5a9f$q$),
  ('c0673553-8dcf-47fd-b89d-18a0ee196d92', '95d38b90-1d15-4c16-99d3-9cfff27f4036', 'ec68e748-74fa-47be-a5da-fe7d4164e33d', $q$Sierra$q$, $q$SIERRA - Digital twin project delivery-Sierra$q$, 7, $q$SIERRA - Digital twin project delivery$q$, $q$<p>Better monitoring and optimization of operations by using digital twins has resulted in a 10% improvement in asset performance and a 20% reduction in operational costs. <strong>Results are 10% higher recovery on remaining reserves and 10% reduction in OPEX.</strong></p>$q$, $q$$q$, null, true, null, null, null, null, 0, true, $q$3d060133-7335-4bfe-a46c-ae9f5122032f$q$),
  ('31801c0a-59a0-4427-912b-04f74fa753ad', '95d38b90-1d15-4c16-99d3-9cfff27f4036', 'ec68e748-74fa-47be-a5da-fe7d4164e33d', $q$Sierra$q$, $q$SIERRA - Digitization project delivery-Sierra$q$, 7, $q$SIERRA - Digitization project delivery$q$, $q$<p>By leveraging digital tools to enhance collaboration and decision-making the digitization project has led to a 25% reduction in operating costs and a 15% increase in production efficiency. <strong>Total effect is a reduced OPEX across the portfolio by 15%.</strong></p>$q$, $q$$q$, null, true, null, null, null, null, 0, true, $q$bae194a0-82fc-43d8-aaf1-8207bee1b878$q$),
  ('cb3c79a5-813e-44dc-9c72-9c436a5a6721', '95d38b90-1d15-4c16-99d3-9cfff27f4036', 'e40fcdf7-31b9-4b9b-8cff-e924d0cc49e5', $q$Amura$q$, $q$1Amura Electrification Andrea-Amura$q$, 8, $q$AMURA - Electrification is highly recommended$q$, $q$<p>The increase in CO2 taxes and the "Electrification Law on Fossil Fuels Producers" has prompted an immediate action for asset owners to electrify AND develop renewable energy compensating the energy needed for the asset.</p><p><br></p><p>Electricity shall replace gas turbines, and the need is 336 Gwh per year. The project CAPEX is 360 MUSD divided over 3 years.</p><p><br></p><p>In addition, you must compensate your electricity consumption by building new renewable capacity. The capacity needed is 40 MW, or more if capacity factor is less than 100%. Needed capacity = 40 MW/CF%.</p><p><br></p><p>You CANNOT procure an already producing asset. Failure to comply will result in an additional 150% CO₂ tax. Please decide on:</p>$q$, $q$1. Electrify and invest in renewables – We have identified or invested in a renewable project to offset electricity consumption.$q$, null, true, null, null, null, null, 0, true, null),
  ('25826c26-987f-4bea-ab32-f6a75dd0a01b', '95d38b90-1d15-4c16-99d3-9cfff27f4036', 'f7e896d1-dea0-43ce-a7a7-7b9426ac8c35', $q$Andrea$q$, $q$1 Electrification Andrea-Andrea$q$, 8, $q$ANDREA - Electrification is highly recommended$q$, $q$<p>The increase in CO2 taxes and the "Electrification Law on Fossil Fuels Producers" has prompted an immediate action for asset owners to electrify AND develop renewable energy compensating the energy needed for the asset.</p><p><br></p><p>Electricity shall replace gas turbines, and the need is 336 Gwh per year. The project CAPEX is 360 MUSD divided over 3 years.</p><p><br></p><p>In addition, you must compensate your electricity consumption by building new renewable capacity. The capacity needed is 40 MW, or more if capacity factor is less than 100%. Needed capacity = 40 MW/CF%.</p><p><br></p><p>You CANNOT procure an already producing asset. Failure to comply will result in an additional 150% CO₂ tax. Please decide on:</p>$q$, $q$1. Electrify and invest in renewables – We have identified or invested in a renewable project to offset electricity consumption.$q$, null, true, null, null, null, null, 0, true, null),
  ('1dad88ba-4c32-43d6-912f-027527c8c13b', '95d38b90-1d15-4c16-99d3-9cfff27f4036', 'f7e896d1-dea0-43ce-a7a7-7b9426ac8c35', $q$Andrea$q$, $q$2 Electrification Andrea NO-Andrea$q$, 8, $q$$q$, $q$$q$, $q$2. Do not electrify – We will continue operating as is and accept a 150% increase in CO₂ tax.$q$, null, true, null, null, null, null, 0, true, null),
