  ('349f7a51-5097-4535-bcd1-a028f0d8164c', '95d38b90-1d15-4c16-99d3-9cfff27f4036', '63734bce-1524-47b3-b0f3-ff83a25bf928', $q$Andora$q$, $q$Andora_Y8_export_Fresco_fluid_issue-Andora$q$, 8, $q$ANDORA - Issue with fluid composition$q$, $q$<p>There is a mis-match between fluid properties, specifically level of mercury. The fluid specification cannot be matched with existing stream from Fresco. </p><p><br></p><p><strong>This has extensive impact of design basis, how will you proceed?</strong></p>$q$, $q$2.Accept a delay of 2 years and additional 120 MUSD in CAPEX.$q$, null, null, null, null, null, null, 0, true, $q$7630cff5-f421-4f31-a709-9a077b52d0a8$q$),
