  ('4d3d829a-b5bc-4ece-9e91-b2dc459fd517', '95d38b90-1d15-4c16-99d3-9cfff27f4036', '63734bce-1524-47b3-b0f3-ff83a25bf928', $q$Andora$q$, $q$1Andora_2Y7_offshoreloading_overruncost-Andora$q$, 8, $q$ANDORA - Overrun on cost / delay$q$, $q$<p>Changes in design will either increase the CAPEX with 300 MUSD and two years delay or 500 MUSD with one year delay. <strong>What is your decision?</strong></p>$q$, $q$1. 1 year delay and 500 MUSD CAPEX.$q$, null, false, null, null, null, null, 0, true, $q$39335756-e238-4523-8e87-46ef988240cc$q$),
