  ('eca829f6-2238-4210-8c91-c53fb472c19c', '95d38b90-1d15-4c16-99d3-9cfff27f4036', 'd6376c30-1d8f-48a1-b26e-0b88f4229d48', $q$Pandora$q$, $q$Y8_Pandora_pipelines_refinery_delayed-Pandora$q$, 8, $q$PANDORA - Landfall project is delayed$q$, $q$<p>The refinery is facing problems with local suppliers and delivery on schedule.</p><p><br></p><p><strong>Will you pay 150 MUSD to ensure schedule or choose one year delay?</strong></p>$q$, $q$2. Accept one year delay.$q$, null, null, null, null, null, null, 0, true, $q$69196da6-f305-4f74-9aae-05d2f00e2df2$q$),
  ('6ddf1cbd-f921-4635-b0f0-dc5a5a79e984', '95d38b90-1d15-4c16-99d3-9cfff27f4036', 'd6376c30-1d8f-48a1-b26e-0b88f4229d48', $q$Pandora$q$, $q$Y7_Pandora_pipelines_refinery_add150 capex-Pandora$q$, 8, $q$$q$, $q$$q$, $q$1. Pay 150 MUSD to ensure schedule are met.$q$, null, true, null, null, null, null, 0, true, $q$69196da6-f305-4f74-9aae-05d2f00e2df2$q$),
  ('17ce2b98-71ce-4b6e-98d6-d8e49d8c9013', '95d38b90-1d15-4c16-99d3-9cfff27f4036', 'd6376c30-1d8f-48a1-b26e-0b88f4229d48', $q$Pandora$q$, $q$2Y8Offshoreloading-Pandora$q$, 8, $q$$q$, $q$$q$, $q$2. 2 year delay and 300 MUSD CAPEX.$q$, null, null, null, null, null, null, 0, true, $q$d96aa4f4-7f91-467e-9269-85edc672c24e$q$),
  ('85437670-83f0-48dc-bbcb-fac09549c0ba', '95d38b90-1d15-4c16-99d3-9cfff27f4036', 'd6376c30-1d8f-48a1-b26e-0b88f4229d48', $q$Pandora$q$, $q$1Y8_Pandora_offshoreloading_overruncost-Pandora$q$, 8, $q$PANDORA - Overrun on cost / delay$q$, $q$<p>Changes in design will either increase the CAPEX with 300 MUSD and two years delay or 500 MUSD with one year delay.</p><p><br></p><p><strong>What is your decision?</strong></p>$q$, $q$1. 1 year delay and 500 MUSD CAPEX.$q$, null, null, null, null, null, null, 0, true, $q$d96aa4f4-7f91-467e-9269-85edc672c24e$q$),
  ('8355b294-c5c2-4103-b547-1810f7e998db', '95d38b90-1d15-4c16-99d3-9cfff27f4036', '85e4ae6e-5665-4759-83f3-5e79a2286d1f', $q$Solstice$q$, $q$Y8 Solstice Gvt support NO$q$, 8, $q$$q$, $q$$q$, $q$1. Governmental contract with fixed price of $90/MWh over 15 years.$q$, null, null, null, null, null, null, 0, true, null),
  ('c85fd8fa-5a11-4af7-a117-7c31f7a485a0', '95d38b90-1d15-4c16-99d3-9cfff27f4036', '85e4ae6e-5665-4759-83f3-5e79a2286d1f', $q$Solstice$q$, $q$Y8 Solstice Gvt support price$q$, 8, $q$Solstice Onshore Wind - Governmental contract offered$q$, $q$<p>Exlandia needs electricity and is offering a support price for your entire production: Fixed price of $90/MWh over the next 15 years.</p><p><br></p><p>The offered price implies that Solstice will not be entitled to the 10% tax cash back presently launched for renewable energy producers.</p><p><br></p><p>There is a requirement to deliver current capacity factor to fulfil the support contract. <strong>The capacity factor can be jeopardised by global climate changes.</strong></p>$q$, $q$2. 10% tax cash back$q$, null, null, null, null, $q$renewable$q$, null, 0, true, null),
  ('4e6418db-2fd1-48e4-83fd-b64ab3a228b2', '95d38b90-1d15-4c16-99d3-9cfff27f4036', 'ec68e748-74fa-47be-a5da-fe7d4164e33d', $q$Sierra$q$, $q$1 Electrification Sierra-Sierra$q$, 8, $q$SIERRA - Electrification is highly recommended$q$, $q$<p>The increase in CO2 taxes and the "Electrification Law on Fossil Fuels Producers" has prompted an immediate action for asset owners to electrify AND develop renewable energy compensating the energy needed for the asset.</p><p><br></p><p>Electricity shall replace gas turbines, and the need is 252 Gwh per year. The project CAPEX is 289 MUSD divided over 3 years.</p><p><br></p><p>In addition, you must compensate your electricity consumption by building new renewable capacity. The capacity needed is 33 MW, or more if capacity factor is less than 100%. Needed capacity = 33 MW/CF%.</p><p><br></p><p>You CANNOT procure an already producing asset. Failure to comply will result in an additional 150% CO₂ tax. Please decide on:</p>$q$, $q$1. Electrify and invest in renewables – We have identified or invested in a renewable project to offset electricity consumption.$q$, null, true, null, null, null, null, 0, true, null),
  ('53fda3d3-8764-4d0c-a3f4-786267e4b51b', '95d38b90-1d15-4c16-99d3-9cfff27f4036', 'ec68e748-74fa-47be-a5da-fe7d4164e33d', $q$Sierra$q$, $q$2 Electrification Sierra-Sierra$q$, 8, $q$$q$, $q$$q$, $q$2. Do not electrify – We will continue operating as is and accept a 150% increase in CO₂ tax.$q$, null, true, null, null, null, null, 0, true, null),
  ('d992b235-1f45-42bd-8c83-520b064d6dcb', '95d38b90-1d15-4c16-99d3-9cfff27f4036', 'f2cac7f8-f0fb-4a03-8e9a-10285af2d1c8', $q$Nostro$q$, $q$2NostroElectrify NO-Nostro$q$, 8, $q$$q$, $q$$q$, $q$2. Do not electrify – We will continue operating as is and accept a 150% increase in CO₂ tax.$q$, null, true, null, null, null, null, 0, true, null),
  ('2adfd904-e717-4885-af32-99ba14996b0e', '95d38b90-1d15-4c16-99d3-9cfff27f4036', 'f2cac7f8-f0fb-4a03-8e9a-10285af2d1c8', $q$Nostro$q$, $q$1NostroElectrification-Nostro$q$, 8, $q$NOSTRO – Electrification$q$, $q$<p>The increase in CO2 taxes and the "Electrification Law on Fossil Fuels Producers" has prompted an immediate action for asset owners to electrify AND develop renewable energy compensating the energy needed for the asset.</p><p><br></p><p>Electricity shall replace gas turbines, and the need at Nostro is 252 Gwh per year. The project CAPEX is 315 MUSD divided over 3 years.</p><p><br></p><p>In addition, you must compensate your electricity consumption by building new renewable capacity. The capacity needed is 30 MW, or more if capacity factor is less than 100%. Needed capacity = 30 MW/CF%.</p><p><br></p><p>You CANNOT procure an already producing asset. Failure to comply will result in an additional 150% CO₂ tax. Please decide on:</p>$q$, $q$1. Electrify and invest in renewables – We have identified or invested in a renewable project to offset electricity consumption.$q$, null, true, null, null, null, null, 3, true, null),
  ('b35c052b-c5d4-4beb-9ac4-ce362681a24b', '95d38b90-1d15-4c16-99d3-9cfff27f4036', '13d5dc12-7917-4a71-bd03-736d0db2b0f2', $q$Tempest$q$, $q$2Community tension$q$, 9, $q$$q$, $q$$q$, $q$2. Pay fine and continue to reject demands.$q$, null, null, null, null, null, null, 0, true, $q$e99d2157-01f1-48c8-b5f0-5d0e49bb9a28$q$),
  ('d37451e1-df26-4fa2-bfee-0492559bc5e3', '95d38b90-1d15-4c16-99d3-9cfff27f4036', '13d5dc12-7917-4a71-bd03-736d0db2b0f2', $q$Tempest$q$, $q$1Community tension$q$, 9, $q$TEMPEST - Resistance has lead to protests$q$, $q$<p>Your resistance towards the endangered species protection requirements has lead to protests and governmental involvement.</p><p><br></p><p><strong>Your company has been issued a fine of $1 M/MW and NGO's are insisting you stop all production until measures have been taken.</strong></p>$q$, $q$1. Invest in environmental studies and take measures to protect wildlife. Additional CAPEX of $0.5 and increased OPEX of $0.005 M/MW.$q$, null, null, null, null, null, null, 0, true, $q$e99d2157-01f1-48c8-b5f0-5d0e49bb9a28$q$),
  ('115fbcd7-5879-446c-b977-ac4b78a8a252', '95d38b90-1d15-4c16-99d3-9cfff27f4036', '13d5dc12-7917-4a71-bd03-736d0db2b0f2', $q$Tempest$q$, $q$Negotiations success$q$, 9, $q$TEMPEST - Negotiations successful$q$, $q$<p>The negotiations with local NGO's and the wildlife protection program has been successful.</p><p><br></p><p><strong>The Tempest Offshore Wind Project will precede as planned.</strong></p>$q$, $q$$q$, null, null, null, null, null, null, 0, true, $q$466ca924-8aa9-4ebe-808b-d74337cde265$q$),
  ('dd3d882b-8bc6-4edf-b291-3e3b9d21066f', '95d38b90-1d15-4c16-99d3-9cfff27f4036', '13d5dc12-7917-4a71-bd03-736d0db2b0f2', $q$Tempest$q$, $q$Governmental involvement$q$, 11, $q$TEMPEST - Governmental involvement and tension$q$, $q$<p>Due to your company's lack of collaboration with the local community and NGO's, the government is forced to take action to meet their demands.</p><p><br></p><p><strong>Capacity factor has been reduced to 44% and OPEX will increase with $0.005 M/MW to meet demands and protect local wildlife.</strong></p>$q$, $q$$q$, null, null, null, 0.44, null, null, 0, true, $q$b35c052b-c5d4-4beb-9ac4-ce362681a24b$q$);
